/*=----------------------------------------------------------------------=*\
   Use :Modifies the internal memory of the LCD to allow for up to 8 customised characters to be created and stored in the device memory
       :
       :Parameters for macro RAMWrite:
       :  Index : Values 0 to 7
       :  d0 : MX_UINT8
       :  d1 : MX_UINT8
       :  d2 : MX_UINT8
       :  d3 : MX_UINT8
       :  d4 : MX_UINT8
       :  d5 : MX_UINT8
       :  d6 : MX_UINT8
       :  d7 : MX_UINT8
\*=----------------------------------------------------------------------=*/
void FCD_01_LCD__RAMWrite(MX_UINT8 FCL_INDEX, MX_UINT8 FCL_D0, MX_UINT8 FCL_D1, MX_UINT8 FCL_D2, MX_UINT8 FCL_D3, MX_UINT8 FCL_D4, MX_UINT8 FCL_D5, MX_UINT8 FCL_D6, MX_UINT8 FCL_D7)
{

	FCD_01_LCD__RawSend(64 + (FCL_INDEX << 3), 0);

	FCI_DELAYBYTE_MS(2);

	FCD_01_LCD__RawSend(FCL_D0, 0x10);

	FCD_01_LCD__RawSend(FCL_D1, 0x10);

	FCD_01_LCD__RawSend(FCL_D2, 0x10);

	FCD_01_LCD__RawSend(FCL_D3, 0x10);

	FCD_01_LCD__RawSend(FCL_D4, 0x10);

	FCD_01_LCD__RawSend(FCL_D5, 0x10);

	FCD_01_LCD__RawSend(FCL_D6, 0x10);

	FCD_01_LCD__RawSend(FCL_D7, 0x10);

	FCD_01_LCD__Clear();

}

