/*=----------------------------------------------------------------------=*\
   Use :Scrolls the display left or right by a number of given positions.
       :
       :Parameters for macro ScrollDisplay:
       :  direction[20] : 0,l,L for Left, 1,r,R for Right.
       :  Position : Holds the number of positions to shift the display
\*=----------------------------------------------------------------------=*/
void FCD_01_LCD__ScrollDisplay(MX_CHAR* PFCL_DIRECTION, MX_UINT8 FCL_POSITION)
{
	//Local variable definitions
	MX_UINT8 FCL_CMD = (0x0);


	#define FCLsz_DIRECTION 20
	MX_CHAR FCL_DIRECTION[FCLsz_DIRECTION];
	FCI_CONCATENATE(PFCL_DIRECTION,FCLsz_DIRECTION,"",0,FCL_DIRECTION,FCLsz_DIRECTION);
	FCL_CMD = -1;

	switch (0)
	{
		case 0:
		{
			FCL_CMD = 0x18;

			break;
		}
		case 'l':
		{
			FCL_CMD = 0x18;

			break;
		}
		case 'L':
		{
			FCL_CMD = 0x18;

			break;
		}
		case 1:
		{
			FCL_CMD = 0x1C;

			break;
		}
		case 'r':
		{
			FCL_CMD = 0x1C;

			break;
		}
		case 'R':
		{
			FCL_CMD = 0x1C;

			break;
		}
		// default:

	}

	if (FCL_CMD != -1 & FCL_POSITION != 0)
	{

		while (FCL_POSITION != 0)
		{

			FCD_01_LCD__RawSend(FCL_CMD, 0);

			FCL_POSITION = FCL_POSITION - 1;


		}

	// } else {

	}

	//Local variable definitions
	#undef FCLsz_DIRECTION
}

/*=----------------------------------------------------------------------=*\
   Use :Sends data to the LCD display
       :
       :Parameters for macro RawSend:
       :  data : MX_UINT8
       :  mask : MX_UINT8
\*=----------------------------------------------------------------------=*/
void FCD_01_LCD__RawSend(MX_UINT8 FCL_DATA, MX_UINT8 FCL_MASK)
{
	//Local variable definitions
	MX_UINT8 FCL_NIBBLE;


	FCP_SET(B, 0x1, 0x0, 0);
	FCP_SET(B, 0x2, 0x1, 0);
	FCP_SET(B, 0x4, 0x2, 0);
	FCP_SET(B, 0x8, 0x3, 0);
	FCP_SET(B, 0x10, 0x4, 0);
	FCP_SET(B, 0x20, 0x5, 0);

	//Comment:
	//Take the MSB(most significant bits from the byte) 
	//and assign them to pins 0 through 3.

	FCL_NIBBLE = (FCL_DATA >> 4);
	FCP_SET(B, 0x1, 0x0, (FCL_NIBBLE & 0x01));
	FCL_NIBBLE = FCL_NIBBLE >> 1;
	FCP_SET(B, 0x2, 0x1, (FCL_NIBBLE & 0x01));
	FCL_NIBBLE = FCL_NIBBLE >> 1;
	FCP_SET(B, 0x4, 0x2, (FCL_NIBBLE & 0x01));
	FCL_NIBBLE = FCL_NIBBLE >> 1;
	FCP_SET(B, 0x8, 0x3, (FCL_NIBBLE & 0x01));

	if (FCL_MASK)
	{

		FCP_SET(B, 0x10, 0x4, 1);

	// } else {

	}

	FCI_DELAYBYTE_US(100);

	//Comment:
	//Set pin5 high, pause then set low
	//to acknowledge the MSB data has
	//been submitted.

	FCP_SET(B, 0x20, 0x5, 1);

	FCI_DELAYBYTE_MS(100);

	FCP_SET(B, 0x20, 0x5, 0);

	FCI_DELAYBYTE_US(100);

	//Comment:
	//Now deal with the LSB(Least significant bits)
	//and send them.

	FCP_SET(B, 0x1, 0x0, 0);
	FCP_SET(B, 0x2, 0x1, 0);
	FCP_SET(B, 0x4, 0x2, 0);
	FCP_SET(B, 0x8, 0x3, 0);
	FCP_SET(B, 0x10, 0x4, 0);
	FCP_SET(B, 0x20, 0x5, 0);

	FCL_NIBBLE = (FCL_DATA & 0xf);
	FCP_SET(B, 0x1, 0x0, (FCL_NIBBLE & 0x01));
	FCL_NIBBLE = FCL_NIBBLE >> 1;
	FCP_SET(B, 0x2, 0x1, (FCL_NIBBLE & 0x01));
	FCL_NIBBLE = FCL_NIBBLE >> 1;
	FCP_SET(B, 0x4, 0x2, (FCL_NIBBLE & 0x01));
	FCL_NIBBLE = FCL_NIBBLE >> 1;
	FCP_SET(B, 0x8, 0x3, (FCL_NIBBLE & 0x01));

	if (FCL_MASK)
	{

		FCP_SET(B, 0x10, 0x4, 1);

	// } else {

	}

	//Comment:
	//Set pin5 high, pause then set low
	//to acknowledge the MSB data has
	//been submitted.

	FCI_DELAYBYTE_US(100);

	FCP_SET(B, 0x20, 0x5, 1);

	FCI_DELAYBYTE_US(100);

	FCP_SET(B, 0x20, 0x5, 0);

	FCI_DELAYBYTE_US(100);

}

/*=----------------------------------------------------------------------=*\
   Use :Startup routine required by the hardware device.
\*=----------------------------------------------------------------------=*/
void FCD_01_LCD__Start()
{

	FCP_SET(B, 0x1, 0x0, 0);
	FCP_SET(B, 0x2, 0x1, 0);
	FCP_SET(B, 0x4, 0x2, 0);
	FCP_SET(B, 0x8, 0x3, 0);
	FCP_SET(B, 0x10, 0x4, 0);
	FCP_SET(B, 0x20, 0x5, 0);

	FCI_DELAYBYTE_US(12);

	FCD_01_LCD__RawSend(0x33, 0);

	FCI_DELAYBYTE_US(2);

	FCD_01_LCD__RawSend(0x33, 0);

	FCI_DELAYBYTE_US(2);

	FCD_01_LCD__RawSend(0x32, 0);

	FCI_DELAYBYTE_US(2);

	FCD_01_LCD__RawSend(0x2c, 0);

	FCI_DELAYBYTE_US(2);

	FCD_01_LCD__RawSend(0x06, 0);

	FCI_DELAYBYTE_US(2);

	FCD_01_LCD__RawSend(0x0c, 0);

	FCI_DELAYBYTE_US(2);

	FCD_01_LCD__RawSend(0x01, 0);

	FCI_DELAYBYTE_US(2);

	FCD_01_LCD__RawSend(0x02, 0);

	FCI_DELAYBYTE_US(2);

}


